func parseBoolExpr(expression string) bool {
	stack := []byte{}
	for i := 0; i < len(expression); i++ {
		c := expression[i]
		switch c {
		case 't', 'f', '(', '!', '&', '|':
			stack = append(stack, c)
		case ')':
			temp := []byte{}
			for stack[len(stack)-1] != '(' {
				temp = append(temp, stack[len(stack)-1])
				stack = stack[:len(stack)-1]
			}
			stack = stack[:len(stack)-1]
			op := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			var res byte
			if op == '!' {
				if temp[0] == 'f' {
					res = 't'
				} else {
					res = 'f'
				}
			} else if op == '&' {
				res = 't'
				for _, x := range temp {
					if x == 'f' {
						res = 'f'
						break
					}
				}
			} else {
				res = 'f'
				for _, x := range temp {
					if x == 't' {
						res = 't'
						break
					}
				}
			}
			stack = append(stack, res)
		}
	}
	return stack[0] == 't'
}

class Solution {
  public boolean parseBoolExpr(String expression) {
    Deque<Character> stack = new ArrayDeque<>();
    for (int i = 0; i < expression.length(); i++) {
      char c = expression.charAt(i);
      if (c == 't' || c == 'f' || c == '(' || c == '!' || c == '&' || c == '|') {
        stack.push(c);
      } else if (c == ')') {
        boolean hasTrue = false, hasFalse = false;
        while (stack.peek() != '(') {
          char x = stack.pop();
          if (x == 't') {
            hasTrue = true;
          } else {
            hasFalse = true;
          }
        }
        stack.pop();
        char op = stack.pop();
        char res;
        if (op == '!') {
          res = hasFalse ? 't' : 'f';
        } else if (op == '&') {
          res = hasFalse ? 'f' : 't';
        } else {
          res = hasTrue ? 't' : 'f';
        }
        stack.push(res);
      }
    }
    return stack.peek() == 't';
  }
}

