impl Solution {
  pub fn parse_bool_expr(expression: String) -> bool {
    let mut stack: Vec<char> = vec![];
    for c in expression.chars() {
      match c {
        't' | 'f' | '(' | '!' | '&' | '|' => stack.push(c),
        ')' => {
          let mut has_true = false;
          let mut has_false = false;
          while *stack.last().unwrap() != '(' {
            let x = stack.pop().unwrap();
            if x == 't' {
              has_true = true;
            } else {
              has_false = true;
            }
          }
          stack.pop();
          let op = stack.pop().unwrap();
          let res = match op {
            '!' => {
              if has_false {
                't'
              } else {
                'f'
              }
            }
            '&' => {
              if has_false {
                'f'
              } else {
                't'
              }
            }
            _ => {
              if has_true {
                't'
              } else {
                'f'
              }
            }
          };
          stack.push(res);
        }
        _ => {}
      }
    }
    stack[0] == 't'
  }
}

const parseBoolExpr = (expression: string): boolean => {
  const stack: string[] = [];
  for (const c of expression) {
    if ('tf(!&|'.includes(c)) {
      stack.push(c);
    } else if (c === ')') {
      let hasTrue = false;
      let hasFalse = false;
      while (stack[stack.length - 1] !== '(') {
        const x = stack.pop()!;
        if (x === 't') hasTrue = true;
        else hasFalse = true;
      }
      stack.pop();
      const op = stack.pop()!;
      let res: string;
      if (op === '!') res = hasFalse ? 't' : 'f';
      else if (op === '&') res = hasFalse ? 'f' : 't';
      else res = hasTrue ? 't' : 'f';
      stack.push(res);
    }
  }
  return stack[0] === 't';
};

class Solution {
public:
  bool parseBoolExpr(string expression) {
    vector<char> stack;

    for (char c : expression) {
      switch (c) {
      case 't':
      case 'f':
      case '(':
      case '!':
      case '&':
      case '|':
        stack.push_back(c);
        break;
      case ')':
        resolve(stack);
      }
    }
    return stack[0] == 't';
  }

  void resolve(vector<char> &stack) {
    vector<char> temp;

    while (stack.back() != '(') {
      temp.push_back(stack.back());
      stack.pop_back();
    }

    stack.pop_back();
    char op = stack.back();
    stack.pop_back();
    if (op == '!')
      stack.push_back(temp[0] == 'f' ? 't' : 'f');
    else if (op == '&')
      stack.push_back(find(temp.begin(), temp.end(), 'f') == temp.end() ? 't' : 'f');
    else if (op == '|')
      stack.push_back(find(temp.begin(), temp.end(), 't') != temp.end() ? 't' : 'f');
  }
};
